pub fn stringProperty(expression: []const u8) ?StringProperty {
    if (equal(expression, "Basic_Emoji")) return .Basic_Emoji;
    if (equal(expression, "Emoji_Keycap_Sequence")) return .Emoji_Keycap_Sequence;
    if (equal(expression, "RGI_Emoji")) return .RGI_Emoji;
    if (equal(expression, "RGI_Emoji_Flag_Sequence")) return .RGI_Emoji_Flag_Sequence;
    if (equal(expression, "RGI_Emoji_Modifier_Sequence")) return .RGI_Emoji_Modifier_Sequence;
    if (equal(expression, "RGI_Emoji_Tag_Sequence")) return .RGI_Emoji_Tag_Sequence;
    if (equal(expression, "RGI_Emoji_ZWJ_Sequence")) return .RGI_Emoji_ZWJ_Sequence;
    return null;
}
pub fn stringSequences(property: StringProperty) []const StringSequence {
    return switch (property) {
        .Basic_Emoji => strings_Basic_Emoji[0..],
        .Emoji_Keycap_Sequence => strings_Emoji_Keycap_Sequence[0..],
        .RGI_Emoji => strings_RGI_Emoji[0..],
        .RGI_Emoji_Flag_Sequence => strings_RGI_Emoji_Flag_Sequence[0..],
        .RGI_Emoji_Modifier_Sequence => strings_RGI_Emoji_Modifier_Sequence[0..],
        .RGI_Emoji_Tag_Sequence => strings_RGI_Emoji_Tag_Sequence[0..],
        .RGI_Emoji_ZWJ_Sequence => strings_RGI_Emoji_ZWJ_Sequence[0..],
    };
}
pub fn stringSequenceValues(sequence: StringSequence) []const u21 {
    return string_values[sequence.offset .. sequence.offset + sequence.length];
}

