    if (equal(expression, "Script=Yiii") or equal(expression, "sc=Yiii") or equal(expression, "Script=Yi") or equal(expression, "sc=Yi")) return contains(script_Yi[0..], codepoint);
    if (equal(expression, "Script_Extensions=Yiii") or equal(expression, "scx=Yiii") or equal(expression, "Script_Extensions=Yi") or equal(expression, "scx=Yi")) return contains(scx_Yi[0..], codepoint) or (!contains(scx_explicit_all[0..], codepoint) and contains(script_Yi[0..], codepoint));
    if (equal(expression, "Script=Zanb") or equal(expression, "sc=Zanb") or equal(expression, "Script=Zanabazar_Square") or equal(expression, "sc=Zanabazar_Square")) return contains(script_Zanabazar_Square[0..], codepoint);
    if (equal(expression, "Script_Extensions=Zanb") or equal(expression, "scx=Zanb") or equal(expression, "Script_Extensions=Zanabazar_Square") or equal(expression, "scx=Zanabazar_Square")) return (!contains(scx_explicit_all[0..], codepoint) and contains(script_Zanabazar_Square[0..], codepoint));
    return null;
}

fn equal(left: []const u8, right: []const u8) bool {
    if (left.len != right.len) return false;
    for (left, right) |a, b| if (a != b) return false;
    return true;
}

fn contains(ranges: []const Range, codepoint: u21) bool {
    var low: usize = 0; var high = ranges.len;
    while (low < high) { const middle = low + (high - low) / 2; const range = ranges[middle];
        if (codepoint < range.first) high = middle else if (codepoint > range.last) low = middle + 1 else return true;
    } return false;
}
